import '../../../../App/Home/data/models/product_preview_entities.dart';class SearchModelState { final bool? loading; final String? message; final bool? success; final List<ProductPreviewEntities>? allProducts; final List<ProductPreviewEntities>? searching;  const SearchModelState({    this.loading,    this.message,    this.success,    this.allProducts=const [],    this.searching,  });  SearchModelState copyWith({    bool? loading,    String? message,    bool? success,    List<ProductPreviewEntities>? allProducts,    List<ProductPreviewEntities>? searching,  }) {    return SearchModelState(      loading: loading ?? this.loading,      message: message ?? this.message,      success: success ?? this.success,      allProducts: allProducts ?? this.allProducts,      searching: searching ?? this.searching,    );  }}